#include <ModbusMaster.h>
ModbusMaster node;
void pre()  { digitalWrite({{de_pin}}, HIGH); }
void post() { digitalWrite({{de_pin}}, LOW); }
void setup() {
    pinMode({{de_pin}}, OUTPUT);
    Serial2.begin(9600);
    node.begin({{slave_id}}, Serial2);
    node.preTransmission(pre);
    node.postTransmission(post);
}
void loop() {
    if (node.readHoldingRegisters({{reg_addr}}, 1) == node.ku8MBSuccess) {
        Serial.println(node.getResponseBuffer(0));
    }
    delay(1000);
}
